// ── Вспомогательные данные ────────────────────────────────

/** Список ролей всех менеджеров */
export const MANAGER_ROLES = MANAGERS.map(m => m.role)

/** Все разрешённые роли включая системные */
export const ALLOWED_ROLES = ['super', 'promo', ...MANAGER_ROLES]

/** Домашний маршрут для каждой роли */
export const ROLE_HOME = {
    super: '/',
    promo: '/',
    ...Object.fromEntries(MANAGERS.map(m => [m.role, m.route])),
}

// ── Вспомогательные функции ───────────────────────────────

/** Найти менеджера по id */
export function getManagerById(id) {
    return MANAGERS.find(m => m.id === id)
}

/** Найти менеджера по роли */
export function getManagerByRole(role) {
    return MANAGERS.find(m => m.role === role)
}

/** Получить цвет по имени ('Стадник' → '#6366f1') */
export function getManagerColor(name) {
    const manager = MANAGERS.find(m => m.name === name)
    return manager ? manager.color : '#94a3b8'
}

/** Получить цвет по роли ('stadnik' → '#6366f1') */
export function getColorByRole(role) {
    if (role === 'super') return 'green'
    if (role === 'promo') return 'dodgerblue'
    const manager = MANAGERS.find(m => m.role === role)
    return manager ? manager.color : 'gray'
}
