        </div>

        <!-- Пилл: иконка пользователя -->
        <div class="header-pill" id="menu-activator">
          <div class="header-avatar"
               :style="{ background: userStatus.isLogin ? 'linear-gradient(135deg,#22c55e,#16a34a)' : '#fee2e2' }">
            <v-icon size="16" color="white">
              {{ userStatus.isLogin ? 'mdi-account-check' : 'mdi-account-remove' }}
            </v-icon>
          </div>
          <span class="header-role" v-if="currentLogin">{{ currentLogin }}</span>
        </div>

        <!-- Кнопка навигации -->
        <button class="header-nav-btn" id="nav-activator" :disabled="userStatus.isBlocked">
          <v-icon size="16" color="white">mdi-menu</v-icon>
          <span v-if="isDesktop">{{ $t('header.navigation') }}</span>
          <span v-else>{{ $t('header.menu') }}</span>
        </button>

        <!-- Меню навигации -->
        <v-menu activator="#nav-activator">
          <v-list style="margin-top:8px;border-radius:14px;overflow:hidden;min-width:190px;padding:6px">
            <v-list-item
                v-for="(item, index) in menuItems"
                :key="index"
                :value="index"
                @click="chooseOperation(item)"
                :style="{ color: item.color }"
                rounded="lg"
            >
              <v-list-item-title style="display:flex;align-items:center;gap:10px;font-size:13px;font-weight:600">
