<template>
  <div class="time-container">
    <div class="time-date">{{ dateString }}</div>
    <div class="time-sep"></div>
    <div class="time-clock">
      {{ hours }}:{{ minutes }}:<span class="time-seconds">{{ seconds }}</span>
    </div>
    <div class="time-sep"></div>
    <div style="color: orange" class="time-date">{{ dateStringDay }}</div>
  </div>
</template>

<script>
export default {
  name: 'TimeComponent',

  data() {
    return {
      seconds:    '',
      minutes:    '',
      hours:      '',
      dateString:    '',
      dateStringDay: '',
      timer:         null,
    }
  },

  mounted() {
    this.updateTime()
    this.timer = setInterval(this.updateTime, 1000)
  },

  beforeUnmount() {
    if (this.timer) clearInterval(this.timer)
  },

  watch: {
    // Пересчитать строку даты при смене языка
    '$i18n.locale'() {
      this.updateTime()
    },
  },

  methods: {
    updateTime() {
      const now = new Date()

      this.seconds = String(now.getSeconds()).padStart(2, '0')
      this.minutes = String(now.getMinutes()).padStart(2, '0')
      this.hours   = String(now.getHours()).padStart(2, '0')

      // Берём дни и месяцы из i18n — реагируют на смену языка
      const days   = this.$tm('time.days')
      const months = this.$tm('time.months')

      const day   = now.getDate()
      const month = months[now.getMonth()]
      const week  = days[now.getDay()]
      const year  = now.getFullYear()

      this.dateString = `${day} ${month} ${year}`
      this.dateStringDay = week
    },
  },
}
</script>

